class Solution {public long solve(int[][] grid){int m=grid.length,n=m==0?0:grid[0].length;if(n==0)return 0;long[][] d=new long[n][n];for(long[] row:d)Arrays.fill(row,-1);d[0][n-1]=(long)grid[0][0]+(n>1?grid[0][n-1]:0);for(int r=1;r<m;r++){long[][] next=new long[n][n];for(long[] row:next)Arrays.fill(row,-1);for(int a=0;a<n;a++)for(int b=0;b<n;b++)if(d[a][b]>=0)for(int da=-1;da<=1;da++)for(int db=-1;db<=1;db++){int x=a+da,y=b+db;if(x>=0&&x<n&&y>=0&&y<n)next[x][y]=Math.max(next[x][y],d[a][b]+grid[r][x]+(x==y?0:grid[r][y]));}d=next;}long best=0;for(long[] row:d)for(long value:row)best=Math.max(best,value);return best;}}